           scanOnBoot.on();
       } else
       if(req.hasParameter("dismiss")) {
           disable(true);
       } else
           throw HttpResponses.error(400,"Invalid request submission: " + req.getParameterMap());

       return HttpResponses.redirectViaContextPath("/manage");
