  id             String  @id @default("singleton")
  restaurantName String  @default("Comandas")
  logoUrl        String?
  brandColorHex  String  @default("#c1401f")

model User {
  id           String   @id @default(cuid())
  name         String
  email        String   @unique
  passwordHash String
  role         Role
  active       Boolean  @default(true)

payments   Payment[]  @relation("PaymentRegisteredBy")
  auditLogs  AuditLog[]

  @@map("users")
}

}

model RestaurantTable {
  id        String      @id @default(cuid())
  number    Int         @unique
  qrToken   String      @unique @default(cuid())
