       RekeySecretAdminMonitor m = new RekeySecretAdminMonitor();  // throw-away instance

       FileBoolean flag = m.scanOnBoot;
       if (flag.isOn()) {
           flag.off();
           m.start(false).join();
           // block the boot until the rewrite process is complete
