                   $this->response_data = $this->_get_all_comments();
               break;

               case "spam":
                   $this->response_data = $this->_get_spam_comments();
               break;

               case "pending":
                   $this->response_data = $this->_get_pending_comments();
               break;

               case "approved":
                   $this->response_data = $this->_get_approved_comments();
               break;

