    * @param $type string
    * @return array
    */
   public function getDefinitions($type)
   {
       if (!method_exists($this, $type)) {
           throw new Exception(sprintf('No such definition set exists for "%s"', $type));
       }

       return (array) Config::get('cms.fileDefinitions.'.$type, $this->$type());
