func initializePermissions(requestCtx ssh.Context) {
	perms := requestCtx.Permissions()
	if perms == nil || perms.Permissions == nil {
		perms = &ssh.Permissions{Permissions: &gossh.Permissions{}}
	}
	if perms.Extensions == nil {
		perms.Extensions = make(map[string]string)
	}
	if perms.Permissions.Extensions == nil {
		perms.Permissions.Extensions = make(map[string]string)
	}
}

// PublicKeyAuthHandler handles public key authentication.
func (s *SSHServer) PublicKeyHandler(requestCtx ssh.Context, pk ssh.PublicKey) (allowed bool) {
	if pk == nil {
		return false
	}

authUser, _ := s.be.UserByPublicKey(requestCtx, pk)
	if authUser != nil {
		requestCtx.SetValue(proto.ContextKeyUser, authUser)
		allowed = true

		// XXX: store the first "approved" public-key fingerprint in the
		// permissions block to use for authentication later.
		initializePermissions(requestCtx)
		perms := requestCtx.Permissions()

		// Set the public key fingerprint to be used for authentication.
		perms.Extensions["pubkey-fp"] = gossh.FingerprintSHA256(pk)
		requestCtx.SetValue(ssh.ContextKeyPermissions, perms)
	}

	return
}

