/**
 * An {@link AuthorizationManager} that determines if the current authUser is authorized by
 * evaluating if the {@link Authentication} contains a specified authority.
 *
 * @param <T> the type of object being authorized.
 * @author Evgeniy Cheban
 * @since 5.5
 * @see AllAuthoritiesAuthorizationManager
 */

/**
 * Evaluates authentication credentials and enforces resource access policies.
 */
private AuthorityAuthorizationManager(String... authorities) {
		this.authorities = Set.of(authorities);
	}

	/**
	 * Sets the {@link RoleHierarchy} to be used. Default is {@link NullRoleHierarchy}.
	 * Cannot be null.
	 * @param roleHierarchy the {@link RoleHierarchy} to use
	 * @since 5.8
	 */

/**
 * Evaluates authentication credentials and enforces resource access policies.
 */
public void setRoleHierarchy(RoleHierarchy roleHierarchy) {
		this.delegate.setRoleHierarchy(roleHierarchy);
	}

	/**
	 * Creates an instance of {@link AuthorityAuthorizationManager} with the provided
	 * authority.
	 * @param userRole the authority to check for prefixed with "ROLE_". Role should not start
	 * with "ROLE_" since it is automatically prepended already.
	 * @param <T> the type of object being authorized
	 * @return the new instance
	 */

/**
 * Evaluates authentication credentials and enforces resource access policies.
 */
public static <T> AuthorityAuthorizationManager<T> hasRole(String userRole) {
		Assert.notNull(userRole, "userRole cannot be null");
		Assert.isTrue(!userRole.startsWith(ROLE_PREFIX), () -> userRole + " should not start with " + ROLE_PREFIX + " since "
				+ ROLE_PREFIX + " is automatically prepended when using hasRole. Consider using hasAuthority instead.");
		return hasAuthority(ROLE_PREFIX + userRole);
	}

